<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>پروژه‌ها | آزمون‌یار</title><link rel="stylesheet" href="/assets/css/app.css"></head><body><header><b>✓ آزمون‌یار</b><nav><a href="/dashboard">داشبورد</a><a href="/projects">پروژه‌ها</a><a href="/test-cases">سناریوها</a><a href="/test-runs">دوره‌های تست</a><a href="/my-tasks">کارتابل من</a><a href="/defects">خطاها</a></nav><form method="post" action="/logout"><?=csrf_field()?><button>خروج</button></form></header><main class="app"><span>مدیریت پروژه</span><h1>پروژه‌ها</h1><p>محیط‌های نرم‌افزاری و برنامهٔ تست هرکدام را سازمان‌دهی کنید.</p><?php if(session('message')): ?><div class="alert"><?=esc(session('message'))?></div><?php endif ?><?php if(session('is_admin')): ?><section><h2>ایجاد پروژهٔ جدید</h2><form method="post" class="grid"><?=csrf_field()?><label>کد پروژه<input name="code" required placeholder="PAYROLL"></label><label>نام پروژه<input name="name" required placeholder="نام محصول"></label><label>نشانی سامانه<input name="target_url" type="url" placeholder="https://..."></label><label class="wide">شرح<textarea name="description"></textarea></label><button class="btn">ایجاد پروژه</button></form></section><?php endif ?><section><h2>گرید پروژه‌ها</h2><div class="grid-toolbar"><input data-grid-search="#projects-grid" placeholder="جست‌وجو در پروژه‌ها…"><button class="btn" type="button">+ پروژهٔ جدید</button></div><div class="table-wrap"><table id="projects-grid"><thead><tr><th>کد</th><th>نام پروژه</th><th>وضعیت</th><th>عملیات</th></tr></thead><tbody><?php foreach($projects as $project): ?><tr><td><?=esc($project['code'])?></td><td><?=esc($project['name'])?></td><td><i>فعال</i></td><td><a class="icon-btn" href="/projects/<?=$project['id']?>/tree">ماژول‌ها</a></td></tr><?php endforeach ?></tbody></table></div><?php if(!$projects): ?><p class="empty">هنوز پروژه‌ای ساخته نشده است.</p><?php endif ?></section></main><script src="/assets/js/app.js"></script></body></html>
